def path8(p,q):
    # shortest 8-conn path: diagonal then straight
    x0,y0=p; x1,y1=q
    cells=[]; x,y=x0,y0
    while x!=x1 and y!=y1:
        x+= (x1>x)-(x1<x); y+=(y1>y)-(y1<y); cells.append((y,x))
    while x!=x1:
        x+=(x1>x)-(x1<x); cells.append((y,x))
    while y!=y1:
        y+=(y1>y)-(y1<y); cells.append((y,x))
    return cells
